    /** The middle of the decomposed sentence; opens on a modal so it never inflects. */
    fun shortRelation(culture: AncientCulture, aspect: AspectType): String = when (culture) {
        AncientCulture.EGYPT -> when (aspect) {
            AspectType.CONJUNCTION -> "cannot be parted from"
            AspectType.SEXTILE -> "can lean on"
            AspectType.SQUARE -> "must haul against"
            AspectType.TRINE -> "can ride the current with"
            AspectType.OPPOSITION -> "must stare across the water at"
        }

        AncientCulture.GREECE -> when (aspect) {
            AspectType.CONJUNCTION -> "must climb the hill beside"
            AspectType.SEXTILE -> "can count on"
            AspectType.SQUARE -> "will quarrel with"
            AspectType.TRINE -> "can walk in step with"
            AspectType.OPPOSITION -> "will take the opposite side from"
        }

        AncientCulture.CANAAN -> when (aspect) {
            AspectType.CONJUNCTION -> "will go up to the council with"
            AspectType.SEXTILE -> "can lend a hand to"
            AspectType.SQUARE -> "will stand in the gate against"
            AspectType.TRINE -> "can work the same field as"
            AspectType.OPPOSITION -> "will bring a claim against"
        }

        AncientCulture.CARTHAGE -> when (aspect) {
            AspectType.CONJUNCTION -> "must sign under one seal with"
            AspectType.SEXTILE -> "can stand surety for"
            AspectType.SQUARE -> "will undercut"
            AspectType.TRINE -> "will tally cleanly with"
            AspectType.OPPOSITION -> "will bid against"
        }

        AncientCulture.ROME -> when (aspect) {
            AspectType.CONJUNCTION -> "must march under one standard with"
            AspectType.SEXTILE -> "can lend troops to"
            AspectType.SQUARE -> "will block the road of"
            AspectType.TRINE -> "can vote with"
            AspectType.OPPOSITION -> "will veto"
        }
    }

    /** The closing reflection per kind. Slot: {god}. */
    fun lesson(culture: AncientCulture, aspect: AspectType): String = when (culture) {
        AncientCulture.EGYPT -> when (aspect) {
            AspectType.CONJUNCTION -> "Two weights in one pan still read as one weight. {god} does not let you claim you carried only half."
            AspectType.SEXTILE -> "A small offering laid on time weighs more than a large one laid late. The scribe writes the date beside every gift."
            AspectType.SQUARE -> "The beam does not tilt to spare you. What tips against you today was already in the pan."
            AspectType.TRINE -> "An easy passage still goes on the scale. {god} records what you did with it."
            AspectType.OPPOSITION -> "The scale has two pans, and you stand in one of them. The beam settles only when you stop pushing on it."
        }

        AncientCulture.GREECE -> when (aspect) {
            AspectType.CONJUNCTION -> "The Pythia answers the question you bring. Bring one, and say it plainly."
            AspectType.SEXTILE -> "The stone heaps at the crossroads were built one traveler at a time. Add yours and keep walking."
            AspectType.SQUARE -> "An oracle that frightens you is still an oracle. Croesus heard what he wanted and lost a kingdom."
            AspectType.TRINE -> "A clear answer is a debt to the god who gave it. Pay it at the altar before you spend it."
            AspectType.OPPOSITION -> "Two heralds can both be honest. The assembly votes, and the losing side still goes home to eat."
        }

        AncientCulture.CANAAN -> when (aspect) {
            AspectType.CONJUNCTION -> "When two matters reach the council together, the elders rule on both. You live with both rulings."
            AspectType.SEXTILE -> "A favor done at the gate is remembered at the gate. The elders keep no tablet, and they forget nothing."
            AspectType.SQUARE -> "A suit you lose at the gate is still settled. Pay what the elders ruled and walk home through the same gate."
            AspectType.TRINE -> "The council says yes once. Ask for what you need, and leave the rest for another sitting."
            AspectType.OPPOSITION -> "Two claims on one field cannot both stand. The council hears both and divides the field, and nobody leaves pleased."
        }

        AncientCulture.CARTHAGE -> when (aspect) {
            AspectType.CONJUNCTION -> "Two entries on one line are paid together. Read the whole line before you sign."
            AspectType.SEXTILE -> "A small credit honored today earns a large one offered later. The clerk remembers who paid on time."
            AspectType.SQUARE -> "A loss written down is smaller than a loss hidden. Enter it, and the book closes."
            AspectType.TRINE -> "A good year in the ledger pays the tithe first. {god}'s share comes off the top, before yours."
            AspectType.OPPOSITION -> "Every bid has a seller across the table. Name your price, and let them name theirs."
        }

        AncientCulture.ROME -> when (aspect) {
            AspectType.CONJUNCTION -> "One standard carries two legions' honor and two legions' blame. March under it knowing both."
            AspectType.SEXTILE -> "A favor asked of a patron is a debt in the patron's book. Pay it before he asks."
            AspectType.SQUARE -> "An adverse omen does not cancel the assembly. It moves the vote to another day, and the business waits."
            AspectType.TRINE -> "The birds on the right are a permission. What you do with it is your own vote."
            AspectType.OPPOSITION -> "A veto stops the motion and leaves the house standing. The vote comes again on another day."
        }
    }

    /** Move one for a natal planet. Slots: {deity}, {sign}, {clause}. */
    fun natalFrame(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "Your birth set {deity} in the {sign}: {clause}."
        AncientCulture.GREECE -> "{deity} stood in the {sign} when you were born: {clause}."
        AncientCulture.CANAAN -> "{deity} sat in the {sign} on the day you were named: {clause}."
        AncientCulture.CARTHAGE -> "The roll of your birth enters {deity} under the {sign}: {clause}."
        AncientCulture.ROME -> "The augurs found {deity} in the {sign} at your birth: {clause}."
    }

    /** Rome's "As {deity} in the {sign}, {clause}." when the clause opens on "you"; empty elsewhere. */
    fun natalFrameYou(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> ""
        AncientCulture.GREECE -> ""
        AncientCulture.CANAAN -> ""
        AncientCulture.CARTHAGE -> ""
        AncientCulture.ROME -> "As {deity} in the {sign}, {clause}."
    }

    /** Move one with no chart. Slots: {god}, {sign}, {domain}. */
    fun skyMoveOne(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "{god} is in the {sign}, weighing {domain}."
        AncientCulture.GREECE -> "{god} walks through the {sign} and answers for {domain}."
        AncientCulture.CANAAN -> "{god} sits in the {sign} and speaks for {domain} before the council."
        AncientCulture.CARTHAGE -> "{god} trades under the {sign} and keeps the books on {domain}."
        AncientCulture.ROME -> "{god} stands in the {sign}, in charge of {domain}."
    }

    /** Move one for a long transit to the rising ("asc") or the midheaven ("mc"). Slot: {sign}. */
    fun angleMoveOne(culture: AncientCulture, angle: String): String = when (culture) {
        AncientCulture.EGYPT -> if (angle == "asc") "The {sign} stood on the eastern horizon when you were born: it is the face you show at the door." else "The {sign} stood overhead when you were born: the nome ranks you by it."
        AncientCulture.GREECE -> if (angle == "asc") "The {sign} was coming up over the hills at your birth, and strangers meet that sign in you first." else "The {sign} held the top of the sky at your birth, and the city judges you under it."
        AncientCulture.CANAAN -> if (angle == "asc") "The {sign} came up over the hills on the day you were named, and the gate knows you by it." else "The {sign} stood highest on the day you were named, and the elders weigh your work under it."
        AncientCulture.CARTHAGE -> if (angle == "asc") "Your birth roll opens under the {sign} rising, the first line every partner reads." else "Your birth roll puts the {sign} at the head of the page, where your standing is entered."
        AncientCulture.ROME -> if (angle == "asc") "The {sign} came up at your birth, and it is the face you bring into the forum." else "The {sign} stood at the height of heaven at your birth, and your career runs under it."
    }

    /** What the rising ("asc") and the midheaven ("mc") govern. */
    fun angleDomain(culture: AncientCulture, angle: String): String = when (culture) {
        AncientCulture.EGYPT -> if (angle == "asc") "the face you show at the door" else "your rank in the nome"
        AncientCulture.GREECE -> if (angle == "asc") "the first impression you make" else "your office in the city"
        AncientCulture.CANAAN -> if (angle == "asc") "the way the gate sees you" else "your seat among the elders"
        AncientCulture.CARTHAGE -> if (angle == "asc") "your face on the quay" else "your standing with the suffetes"
        AncientCulture.ROME -> if (angle == "asc") "the face you bring into the forum" else "your career in office"
    }

    /** Slot: {interval}. */
    fun recurrenceFrame(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "This figure comes round on the river again {interval}."
        AncientCulture.GREECE -> "The tripod hears this figure again {interval}."
        AncientCulture.CANAAN -> "This matter comes before the council again {interval}."
        AncientCulture.CARTHAGE -> "This entry falls due again {interval}."
        AncientCulture.ROME -> "The augurs record this figure again {interval}."
    }

    fun playsOutTitle(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "HOW THIS PLAYS OUT ON THE RIVER"
        AncientCulture.GREECE -> "HOW THIS PLAYS OUT AT THE TRIPOD"
        AncientCulture.CANAAN -> "HOW THIS PLAYS OUT IN THE COUNCIL"
        AncientCulture.CARTHAGE -> "HOW THIS PLAYS OUT ON THE LEDGER"
        AncientCulture.ROME -> "HOW THIS PLAYS OUT IN THE FORUM"
    }

    /** A long transit's act line, per slow body. Slot: {god}. */
    fun slowAct(culture: AncientCulture, body: Planet): String = when (culture) {
        AncientCulture.EGYPT -> when (body) {
            Planet.JUPITER -> "{god} sends the flood a cubit higher, and the granary scribes call for more jars."
            Planet.SATURN -> "{god} lies still under the field, and the surveyor walks the old boundary again."
            Planet.URANUS -> "{god} spreads her body over the roof beams, and the old plaster comes down."
            Planet.NEPTUNE -> "{god} wells up under the fields, and the boundary stones go under water."
            Planet.PLUTO -> "{god} sits in judgment in the lower hall, and the scribe reads out what you buried."
            else -> error("$body has no slow act")
        }

        AncientCulture.GREECE -> when (body) {
            Planet.JUPITER -> "{god} nods from Olympus, and the assembly gives you the floor."
            Planet.SATURN -> "{god} counts the sheaves at the threshing floor, and the short ones are set aside."
            Planet.URANUS -> "{god} spreads the sky wider, and the city walls look small under it."
            Planet.NEPTUNE -> "{god} stirs the harbor, and the moorings slip one by one."
            Planet.PLUTO -> "{god} opens the storerooms under the earth, and old silver comes up with the plow."
            else -> error("$body has no slow act")
        }

        AncientCulture.CANAAN -> when (body) {
            Planet.JUPITER -> "{god} thunders from the cloud, and the rain falls on your terraces first."
            Planet.SATURN -> "{god} sits at the head of the council, and every case waits for his word."
            Planet.URANUS -> "{god} moves the bounds of the sky, and the flock follows the fresh grass."
            Planet.NEPTUNE -> "{god} rolls against the shore, and the fishermen drag their boats higher."
            Planet.PLUTO -> "{god} opens his throat at the edge of the field, and old losses come back to mind."
            else -> error("$body has no slow act")
        }

        AncientCulture.CARTHAGE -> when (body) {
            Planet.JUPITER -> "{god} opens the temple treasury, and the loans go out at a low rate."
            Planet.SATURN -> "{god} calls in the old accounts, and the clerks work by lamplight."
            Planet.URANUS -> "{god} blows the storm off its usual course, and the captains chart another passage."
            Planet.NEPTUNE -> "{god} hides the coastline in fog, and every pilot slows."
            Planet.PLUTO -> "{god} opens the family tomb for an audit, and the heirs gather at the door."
            else -> error("$body has no slow act")
        }

        AncientCulture.ROME -> when (body) {
            Planet.JUPITER -> "{god} thunders on the left, and the magistrate takes office under good auspices."
            Planet.SATURN -> "{god} has the wool unbound from his statue's feet, and the city keeps holiday."
            Planet.URANUS -> "{god} spreads his mantle over the city, and the old laws look narrow under it."
            Planet.NEPTUNE -> "{god} stirs the sea off Ostia, and the grain fleet waits in harbor."
            Planet.PLUTO -> "{god} opens the mundus, and the dead have the city for the day."
            else -> error("$body has no slow act")
        }
    }

    /** Four manifestations per (house group 0 to 3, tone). */
    fun manifestations(culture: AncientCulture, group: Int, harmony: Boolean): List<String> = when (culture) {
        AncientCulture.EGYPT -> when (group) {
            0 -> if (harmony) listOf("a ration of emmer measured out in full", "the overseer passing your row without a word", "a jar of oil left over at the month's end", "your tally matching the scribe's at the first count") else listOf("a short measure at the granary door", "the overseer counting your bricks twice", "a debt of grain you forgot you owed", "a sledge rope fraying halfway to the site")
            1 -> if (harmony) listOf("bread and beer shared on the roof at dusk", "a mother's name said kindly at the table", "the offering table for the ancestors swept and set", "a child who sleeps through the night") else listOf("an old argument over the family field", "the lamp in the ancestor's niche gone out", "a brother asking for his share again", "a house too small for everyone in it")
            2 -> if (harmony) listOf("a letter that arrives before you looked for it", "the ferryman waving you aboard without the fee", "a neighbor who carries your message across", "a contract read once and sealed") else listOf("a letter answered in the wrong tone", "a boat that leaves the bank without you", "a witness who remembers the words differently", "the same question put to you three times")
            3 -> if (harmony) listOf("an hour alone with the door shut", "a dream you remember clearly at waking", "incense that burns down evenly", "a vow you keep without anyone watching") else listOf("a sleepless hour before the dawn hymn", "a secret that sits heavy in the chest", "an amulet worn once and then forgotten", "a fear you cannot put a name to")
            else -> error("no house group $group")
        }

        AncientCulture.GREECE -> when (group) {
            0 -> if (harmony) listOf("a fair price at the first stall", "silver counted out with nothing missing", "a buyer who comes back for more", "your goods sold before the market closes") else listOf("a merchant who weighs with his thumb", "the tax farmer at your door before noon", "an obol short at the end of the day", "goods spoiled on the road to the agora")
            1 -> if (harmony) listOf("the whole household at one table", "the hearth fire caught on the first try", "a guest who brings his own wine", "an old quarrel left at the threshold") else listOf("a sharp word over the loom", "the hearth smoking out the room", "a relative who stays three days too long", "the dowry argued over again")
            2 -> if (harmony) listOf("a message carried right the first time", "a stranger on the road who knows the way", "a friend who answers before you finish asking", "the right word at the crossroads") else listOf("a rumor that reaches the agora before you", "a wrong turn at the herm", "a friend who repeats what you told him in confidence", "a letter delivered to the wrong house")
            3 -> if (harmony) listOf("a quiet hour before the lamp is lit", "an answer that comes to you while walking", "a dream worth telling at breakfast", "the oracle's words making sense at last") else listOf("a question you are afraid to ask aloud", "a dream you would rather not have interpreted", "a bad omen you keep turning over", "the riddle that wakes you at night")
            else -> error("no house group $group")
        }

        AncientCulture.CANAAN -> when (group) {
            0 -> if (harmony) listOf("a full floor of sheaves before the heat", "an ox that pulls without the goad", "a jar of oil pressed on the first try", "your field's share counted honestly") else listOf("a broken plowshare on the stony row", "locusts on the neighbor's field and yours", "a hired hand who does not come back", "the tithe collector at the threshing floor")
            1 -> if (harmony) listOf("the clan gathered for the first wine", "a cousin's wedding where everyone comes", "the boundary stone left where your grandfather set it", "an elder who takes your side") else listOf("a quarrel over the birthright", "a widow in the family who needs bread", "an inheritance split three ways", "a shut tent flap where there was welcome")
            2 -> if (harmony) listOf("two witnesses who agree on every word", "a traveler at the gate with good news", "a bargain sealed with a handclasp", "your name spoken well among the elders") else listOf("a witness who changes his story", "a suit brought against you at the gate", "a neighbor's oath you cannot trust", "gossip carried up from the well")
            3 -> if (harmony) listOf("a prayer said without stumbling", "an evening with the lamp and no visitors", "a vow fulfilled on the day you named", "sleep that comes without dreams of debt") else listOf("a vow made in haste", "an evil dream after a feast", "a sacrifice the priest turns away", "a silence where an answer should be")
            else -> error("no house group $group")
        }

        AncientCulture.CARTHAGE -> when (group) {
            0 -> if (harmony) listOf("a ledger that closes on the first count", "wages paid on the day they fall due", "silver weighed and found full", "a buyer who pays before delivery") else listOf("a coin that rings false on the table", "a clerk's error in the other party's favor", "a cargo valued below its cost", "interest added to a loan you thought was settled")
            1 -> if (harmony) listOf("the household books agreed by everyone", "an heir who learns the trade", "a dowry paid on time", "a courtyard full at the festival meal") else listOf("an heir who wants his share early", "a steward who loses the keys", "a will read aloud and disputed", "household silver spent before the month is out")
            2 -> if (harmony) listOf("a ship that arrives a day early", "a letter from Gades with good prices", "a captain who keeps his word", "a berth free when you need one") else listOf("a ship held in port by the wind", "a tally that does not match the cargo", "a partner's letter that contradicts the last one", "news from Tyre that arrives too late")
            3 -> if (harmony) listOf("a vow paid and a stele set up", "an hour of quiet in the precinct", "a priest who accepts the offering at once", "a promise you keep without witnesses") else listOf("a vow you have not yet paid", "a sleepless night over a contract", "an omen at the altar you cannot read", "a secret you have kept too long")
            else -> error("no house group $group")
        }

        AncientCulture.ROME -> when (group) {
            0 -> if (harmony) listOf("a client who pays his respects at dawn", "a motion carried without debate", "a contract witnessed and sealed", "your name read out with approval") else listOf("a petition that comes back unsigned", "a debt nobody will name at the table", "a rival who takes the front bench first", "a magistrate who will not see you today")
            1 -> if (harmony) listOf("the Lares fed and the hearth kept bright", "a dinner where every couch is full", "a freedman who serves your house well", "an ancestor's mask honored in the atrium") else listOf("a quarrel over a dowry", "a servant who breaks the good cup", "an heir who expects more than his share", "the household gods neglected for a week")
            2 -> if (harmony) listOf("a courier who arrives a day ahead", "a friend's letter with good news from the provinces", "a road clear all the way to the gate", "an introduction that opens a door") else listOf("a dispatch lost at a river crossing", "the urge to settle it by shouting", "a friend who forgets your appointment", "a rumor from the baths that reaches the Senate")
            3 -> if (harmony) listOf("a morning at the shrine with no one else there", "an omen from the right side", "a dream that answers a question", "a vow you renew without being asked") else listOf("a door that stays shut until you stop pushing", "an augury put off for another day", "a vow you made and have not kept", "a sleepless night before a decision")
            else -> error("no house group $group")
        }
    }

