    /** The placement paragraph's one second-person clause, as placementClause recasts it on web. */
    fun placementClause(planet: Planet, sign: ZodiacSign): String = when (planet) {
        Planet.SUN -> when (sign) {
            ZodiacSign.ARIES -> "you reach for what you want before deliberation"
            ZodiacSign.TAURUS -> "what you decide stays decided"
            ZodiacSign.GEMINI -> "the version of you that speaks is the one you keep, and the one that stays quiet never gets built"
            ZodiacSign.CANCER -> "your power arrives as care and is spent the same way"
            ZodiacSign.LEO -> "you are warmer when seen"
            ZodiacSign.VIRGO -> "you improve the object and become more yourself in the improving"
            ZodiacSign.LIBRA -> "you are legible to yourself only across a table"
            ZodiacSign.SCORPIO -> "low stakes put you to sleep"
            ZodiacSign.SAGITTARIUS -> "move in a direction and you are somebody"
            ZodiacSign.CAPRICORN -> "you feel real when you have built something"
            ZodiacSign.AQUARIUS -> "you wake when the group misnames you"
            ZodiacSign.PISCES -> "you lose your edges and find yourself in the losing"
        }
        Planet.MOON -> when (sign) {
            ZodiacSign.ARIES -> "your gut moves before your reasoning"
            ZodiacSign.TAURUS -> "you change slowly and root deep"
            ZodiacSign.GEMINI -> "nothing has happened to you until you have said it out loud to somebody"
            ZodiacSign.CANCER -> "you feel the shape of the room you walked into ten years ago"
            ZodiacSign.LEO -> "you live the day in scenes, with entrances and a curtain"
            ZodiacSign.VIRGO -> "the to-do list is where your moods surface"
            ZodiacSign.LIBRA -> "you take your weather from the person across from you"
            ZodiacSign.SCORPIO -> "you skip the small surfaces"
            ZodiacSign.SAGITTARIUS -> "the body wants the wider room"
            ZodiacSign.CAPRICORN -> "you handle the day by doing the day"
            ZodiacSign.AQUARIUS -> "your moods arrive already annotated"
            ZodiacSign.PISCES -> "you take on the mood of the room"
        }
        Planet.MERCURY -> when (sign) {
            ZodiacSign.ARIES -> "you find out what you think by hearing yourself say it"
            ZodiacSign.TAURUS -> "you decide once, and the decision sets"
            ZodiacSign.GEMINI -> "you think in conversation, in branches, in echoes"
            ZodiacSign.CANCER -> "you think backward from how things landed"
            ZodiacSign.LEO -> "you think toward the room, and the room's face edits the sentence"
            ZodiacSign.VIRGO -> "you sort, and then you sort the sorting"
            ZodiacSign.LIBRA -> "you hold both arguments"
            ZodiacSign.SCORPIO -> "you think by following what people are hiding, including from themselves"
            ZodiacSign.SAGITTARIUS -> "you think in arcs and frames"
            ZodiacSign.CAPRICORN -> "an idea that cannot carry weight does not hold you"
            ZodiacSign.AQUARIUS -> "you think by the diagram of the whole"
            ZodiacSign.PISCES -> "you think in mood and metaphor"
        }
        Planet.VENUS -> when (sign) {
            ZodiacSign.ARIES -> "you go for it before the wanting has cooled into a plan"
            ZodiacSign.TAURUS -> "you love what stays, and you price things by how they sit in the hand"
            ZodiacSign.GEMINI -> "you are drawn by minds that move"
            ZodiacSign.CANCER -> "you love by feeding"
            ZodiacSign.LEO -> "you love by making the other beautiful"
            ZodiacSign.VIRGO -> "you love by improving what is in front of you"
            ZodiacSign.LIBRA -> "you complete yourself in another"
            ZodiacSign.SCORPIO -> "you love at depth or you do not love at all"
            ZodiacSign.SAGITTARIUS -> "what teaches you is what you want"
            ZodiacSign.CAPRICORN -> "you court in decades and prove yourself by showing up"
            ZodiacSign.AQUARIUS -> "you love by election"
            ZodiacSign.PISCES -> "you love by losing the line"
        }
        Planet.MARS -> when (sign) {
            ZodiacSign.ARIES -> "you push to find the resistance"
            ZodiacSign.TAURUS -> "once you are moving, nothing redirects you, and nothing starts you either"
            ZodiacSign.GEMINI -> "your force splits"
            ZodiacSign.CANCER -> "you push by protecting"
            ZodiacSign.LEO -> "your fight wants a witness"
            ZodiacSign.VIRGO -> "you push by refining"
            ZodiacSign.LIBRA -> "your force runs through the other person"
            ZodiacSign.SCORPIO -> "you push at depth and at the right moment"
            ZodiacSign.SAGITTARIUS -> "you throw further than the ground you have covered"
            ZodiacSign.CAPRICORN -> "you push by enduring"
            ZodiacSign.AQUARIUS -> "your fight belongs to a rule rather than a grudge"
            ZodiacSign.PISCES -> "you move things by mood, by suggestion, by being unavailable at the right hour"
        }
        Planet.JUPITER -> when (sign) {
            ZodiacSign.ARIES -> "you are given more each time you begin"
            ZodiacSign.TAURUS -> "what increases here is what you can hold"
            ZodiacSign.GEMINI -> "you collect languages, contacts, half-read books, and the collection is real wealth"
            ZodiacSign.CANCER -> "you take people in and the household widens"
            ZodiacSign.LEO -> "you give warmth away and more of it comes back"
            ZodiacSign.VIRGO -> "increase is refinement"
            ZodiacSign.LIBRA -> "the other person's world opens into yours and doubles what you can reach"
            ZodiacSign.SCORPIO -> "what you let die comes back multiplied, which makes killing things feel like a method"
            ZodiacSign.SAGITTARIUS -> "nothing here needs an occasion to get bigger"
            ZodiacSign.CAPRICORN -> "increase is laid brick after brick and it arrives late"
            ZodiacSign.AQUARIUS -> "you are enlarged by the idea you belong to, and the bigger the idea the bigger the return"
            ZodiacSign.PISCES -> "the increase here has no edges"
        }
        Planet.SATURN -> when (sign) {
            ZodiacSign.ARIES -> "the first move meets a wall, every time, until the moves get fewer and better aimed"
            ZodiacSign.TAURUS -> "what survives this is the only thing you will still own in twenty years"
            ZodiacSign.GEMINI -> "you are taught focus by running out of it in public"
            ZodiacSign.CANCER -> "there is a family here you cannot repair, and no competence you acquire will change that"
            ZodiacSign.LEO -> "the applause does not come"
            ZodiacSign.VIRGO -> "you learn the difference between maintenance and mastery"
            ZodiacSign.LIBRA -> "limit shows up in the relationship that asks you to choose yourself first"
            ZodiacSign.SCORPIO -> "what you held back has to come up, on a schedule you did not set"
            ZodiacSign.SAGITTARIUS -> "you are taught arrival by being denied it, again, on schedule"
            ZodiacSign.CAPRICORN -> "limit is your native register"
            ZodiacSign.AQUARIUS -> "you learn that the rule needs its exception, and you learn it from the person the rule crushed"
            ZodiacSign.PISCES -> "limit shows up as the line you finally have to draw"
        }
        Planet.URANUS -> when (sign) {
            ZodiacSign.ARIES -> "you break from the inherited form before anyone finishes the sentence"
            ZodiacSign.TAURUS -> "you hold your form long past comfort, then overturn it whole"
            ZodiacSign.GEMINI -> "you change the subject and the subject changes the room"
            ZodiacSign.CANCER -> "you walk out of the inherited home to build one that fits, and the grief goes out the door with you"
            ZodiacSign.LEO -> "you walk off the script mid-scene, in front of the people who bought tickets for the old show"
            ZodiacSign.VIRGO -> "you find the broken part of the routine and tear out the whole routine to reach it"
            ZodiacSign.LIBRA -> "you break the peace that required your silence"
            ZodiacSign.SCORPIO -> "you bury the pressure until it chooses its moment"
            ZodiacSign.SAGITTARIUS -> "you break from the doctrine you were raised inside"
            ZodiacSign.CAPRICORN -> "you break the ladder you spent years climbing and hand back the rank that came with it"
            ZodiacSign.AQUARIUS -> "rupture is the house you already live in"
            ZodiacSign.PISCES -> "you slip inherited forms without a fight"
        }
        Planet.NEPTUNE -> when (sign) {
            ZodiacSign.ARIES -> "you charge at causes larger than yourself"
            ZodiacSign.TAURUS -> "you make an idol of what the hand closes on, and the held thing blurs anyway"
            ZodiacSign.GEMINI -> "you speak in tides, and words blur into music"
            ZodiacSign.CANCER -> "the line between your feelings and the family's disappears"
            ZodiacSign.LEO -> "you perform an ideal self and begin to believe it"
            ZodiacSign.VIRGO -> "you give service until the giver goes missing"
            ZodiacSign.LIBRA -> "you see the partner as they could be, and you go on loving the picture long after the person has walked out of it"
            ZodiacSign.SCORPIO -> "you merge where others keep a floor"
            ZodiacSign.SAGITTARIUS -> "you believe wider than any single creed, wide enough that the belief stops issuing instructions"
            ZodiacSign.CAPRICORN -> "the summit keeps receding into fog and you keep climbing toward it"
            ZodiacSign.AQUARIUS -> "you dream the collective before it exists"
            ZodiacSign.PISCES -> "dissolution is your native water"
        }
        Planet.PLUTO -> when (sign) {
            ZodiacSign.ARIES -> "you are rebuilt by the fights you could not walk away from"
            ZodiacSign.TAURUS -> "power lives in what you hold"
            ZodiacSign.GEMINI -> "you dig with questions until something opens"
            ZodiacSign.CANCER -> "the house you came from gets torn open until its foundations are in plain view"
            ZodiacSign.LEO -> "pride is taken from you in front of everyone"
            ZodiacSign.VIRGO -> "you purge by fixing, sorting, cutting away, and the flaw you found first is the one you never stop seeing"
            ZodiacSign.LIBRA -> "the other person carries what you buried, and the bond drags it up"
            ZodiacSign.SCORPIO -> "you go to the bottom of things because the bottom is where you live"
            ZodiacSign.SAGITTARIUS -> "power moves through conviction"
            ZodiacSign.CAPRICORN -> "what you built gets stripped to bedrock"
            ZodiacSign.AQUARIUS -> "you see the machinery others call natural"
            ZodiacSign.PISCES -> "the deepest losses here have no edges and no name"
        }
    }

